def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid line that acts as the barrier.
    barrier = None
    for r in range(h):
        if grid[r][0] != 0 and all(x == grid[r][0] for x in grid[r]):
            barrier = ("row", r)
            break
    if barrier is None:
        for c in range(w):
            if grid[0][c] != 0 and all(grid[r][c] == grid[0][c] for r in range(h)):
                barrier = ("col", c)
                break
    if barrier is None:
        return [row[:] for row in grid]

    out = [[0] * w for _ in range(h)]
    fixed = set()
    if barrier[0] == "row":
        _, br = barrier
        for c in range(w):
            out[br][c] = grid[br][c]
            fixed.add((br, c))
        dr, dc = (-1, 0) if br < h // 2 else (1, 0)
    else:
        _, bc = barrier
        for r in range(h):
            out[r][bc] = grid[r][bc]
            fixed.add((r, bc))
        dr, dc = (0, -1) if bc < w // 2 else (0, 1)

    # Extract connected, same-color objects, excluding the barrier.
    seen = set(fixed)
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                rr, cc = stack.pop()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc),
                               (rr, cc - 1), (rr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))
            objects.append(cells)

    # Move objects nearest the barrier first.
    if dr < 0:
        objects.sort(key=lambda cells: min(r for r, _ in cells))
    elif dr > 0:
        objects.sort(key=lambda cells: -max(r for r, _ in cells))
    elif dc < 0:
        objects.sort(key=lambda cells: min(c for _, c in cells))
    else:
        objects.sort(key=lambda cells: -max(c for _, c in cells))

    for cells in objects:
        color = grid[cells[0][0]][cells[0][1]]
        shift = 0
        while True:
            next_cells = [(r + dr * (shift + 1), c + dc * (shift + 1))
                          for r, c in cells]
            if any(not (0 <= nr < h and 0 <= nc < w) or out[nr][nc] != 0
                   for nr, nc in next_cells):
                break
            shift += 1
        for r, c in cells:
            out[r + dr * shift][c + dc * shift] = color

    return out
